import numpy as np

def calculate_snr(spectrum):
    # Simple SNR estimate: (Peak - Baseline) / RMS_noise
    # We use the max peak and a region for noise.
    y = spectrum['intensity']
    x = spectrum['raman_shift']

    # Find main peak
    peak_idx = np.argmax(y)
    peak_val = y[peak_idx]

    # Baseline: use the first 50 pixels as noise region
    noise_region = y[:50]
    baseline = np.mean(noise_region)
    sigma = np.std(noise_region)

    snr = (peak_val - baseline) / sigma if sigma > 0 else 0
    return snr, peak_val

